\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usepackage{amsmath}
\usetikzlibrary{arrows} 
\usetikzlibrary{intersections} 
\usetikzlibrary{patterns} 
\usetikzlibrary{decorations.pathreplacing} 
\usepgfplotslibrary{fillbetween} 
\usetikzlibrary{shapes,positioning}

\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}[
squarednode/.style={rectangle, draw=none, fill=white, minimum size=7mm, rounded corners=1mm},
node distance=2cm and 3cm,
>=stealth,
]

%Nodes
\node[squarednode] (x_C) {$[\mathbf{x}]_{\color{red}\mathcal{C}}$};
\node[squarednode] (T_Cx_C) [right=of x_C] {$[\mathbf{T}(\mathbf{x})]_{\color{red}\mathcal{C}}$};
\node[squarednode] (x_B) [below=of x_C]	{$[\mathbf{x}]_{\color{blue}\mathcal{B}}$};
\node[squarednode] (T_Bx_B) [below=of T_Cx_C] {$[\mathbf{T}(\mathbf{x})]_{\color{blue}\mathcal{B}}$};

%Lines
\draw[->, red, line width=1.5pt] (x_C.east) -- (T_Cx_C.west) node[midway, above, black] {$[\mathbf{T}]_{\color{red}\mathcal{C}}$};
\draw[->, blue, line width=1.5pt] (x_C.south) -- (x_B.north) node[midway, left] {${\color{black}P}_{\small{\color{blue}\mathcal{B}}{\color{black}\to}{\color{red}\mathcal{C}}}^{\color{black}-1}$};
\draw[->, blue, line width=1.5pt] (x_B.east) -- (T_Bx_B.west) node[midway, below] {${\color{black}[\mathbf{T}]}_{\mathcal{B}}$};
\draw[->, blue, line width=1.5pt] (T_Bx_B.north) -- (T_Cx_C.south) node[midway, right] {${\color{black}P}_{\small{\color{blue}\mathcal{B}}{\color{black}\to}{\color{red}\mathcal{C}}}$};;

\end{tikzpicture}
